const AUTH_BASE_URL = 'http://localhost:8081/auth';
const API_BASE_URL = 'http://localhost:8080'; // întrebări, răspunsuri etc.


async function request(path, options = {}) {
  // Alege baza URL în funcție de prefix
  const baseUrl = path.startsWith('/auth') || path === '/login' || path === '/register'
    ? AUTH_BASE_URL
    : API_BASE_URL;

  let headers = {
    'Content-Type': 'application/json',
    ...options.headers,
  };

  // Adaugă token-ul DOAR pentru endpoint-urile care NU sunt /answers/question/
  if (!path.startsWith('/answers/question/')) {
      const token = localStorage.getItem('token');
      if (token) {
          headers = { ...headers, Authorization: `Bearer ${token}` };
      }
  }

  const response = await fetch(`${baseUrl}${path}`, {
    credentials: 'include',
    headers,
    ...options,
  });

  if (!response.ok) {
    let errMsg = `Request failed: ${response.status}`;
    try {
      const errJson = await response.json();
      errMsg = errJson.message || errMsg;
    } catch {} // Ignore parsing errors
    throw new Error(errMsg);
  }

  const contentType = response.headers.get('content-type') || '';
  if (contentType.includes('application/json')) {
    return response.json();
  } else {
    return { message: await response.text() };
  }
}

 
export function login(credentials) {
  return request('/login', {
    method: 'POST',
    body: JSON.stringify(credentials),
  });
}

export function register(data) {
  return request('/register', {
    method: 'POST',
    body: JSON.stringify(data),
  });
}

 
export function getQuestions() {
  return request('/questions');
}

export function getQuestionById(id) {
  return request(`/questions/${id}`);
}

export function postQuestion(question) {
  return request('/questions', {
    method: 'POST',
    body: JSON.stringify(question),
  });
}

 
export function getAnswersByQuestionId(questionId) {
  return request(`/answers/question/${questionId}`);
}

export function postAnswer(answer) {
  return request('/answers', {
    method: 'POST',
    body: JSON.stringify(answer),
  });
}
